package com.ianblk.zianmobs;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.neoforge.client.event.EntityRenderersEvent;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.model.GeoModel;
import software.bernie.geckolib.renderer.GeoEntityRenderer;
@EventBusSubscriber(modid="zianmobs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class MobsClient {
 @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){for(var type:java.util.List.of(Mobs.FOREST,Mobs.ICE,Mobs.CRYSTAL))event.registerEntityRenderer(type.get(),context->new GeoEntityRenderer<>(context,new Model()));event.registerEntityRenderer(Mobs.ONI.get(),context->new GeoEntityRenderer<>(context,new Model()));event.registerEntityRenderer(Mobs.NPC.get(),com.ianblk.zianmobs.client.CombatNpcRenderer::new);event.registerEntityRenderer(Mobs.PROJECTILE.get(),net.minecraft.client.renderer.entity.ThrownItemRenderer::new);}
 @SubscribeEvent public static void setup(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent event){event.enqueueWork(()->{com.ianblk.zianmobs.client.ClientSmoke.register();net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(com.ianblk.zianmobs.client.ZoneLines::render);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(com.ianblk.zianmobs.client.ZoneLines::tick);for(var deferred:Gear.ITEMS.values()){var item=deferred.get();if(item instanceof net.minecraft.world.item.BowItem){net.minecraft.client.renderer.item.ItemProperties.register(item,ResourceLocation.withDefaultNamespace("pull"),(stack,level,entity,seed)->entity!=null&&entity.getUseItem()==stack?(stack.getUseDuration(entity)-entity.getUseItemRemainingTicks())/(float)EnhancedBow.DRAW_TICKS:0);net.minecraft.client.renderer.item.ItemProperties.register(item,ResourceLocation.withDefaultNamespace("pulling"),(stack,level,entity,seed)->entity!=null&&entity.isUsingItem()&&entity.getUseItem()==stack?1:0);}if(item instanceof net.minecraft.world.item.CrossbowItem){net.minecraft.client.renderer.item.ItemProperties.register(item,ResourceLocation.withDefaultNamespace("charged"),(stack,level,entity,seed)->net.minecraft.world.item.CrossbowItem.isCharged(stack)?1:0);net.minecraft.client.renderer.item.ItemProperties.register(item,ResourceLocation.withDefaultNamespace("pulling"),(stack,level,entity,seed)->entity!=null&&entity.isUsingItem()&&entity.getUseItem()==stack&&!net.minecraft.world.item.CrossbowItem.isCharged(stack)?1:0);net.minecraft.client.renderer.item.ItemProperties.register(item,ResourceLocation.withDefaultNamespace("pull"),(stack,level,entity,seed)->entity!=null&&entity.getUseItem()==stack?(stack.getUseDuration(entity)-entity.getUseItemRemainingTicks())/(float)net.minecraft.world.item.CrossbowItem.getChargeDuration(stack,entity):0);net.minecraft.client.renderer.item.ItemProperties.register(item,ResourceLocation.withDefaultNamespace("firework"),(stack,level,entity,seed)->stack.getOrDefault(net.minecraft.core.component.DataComponents.CHARGED_PROJECTILES,net.minecraft.world.item.component.ChargedProjectiles.EMPTY).contains(net.minecraft.world.item.Items.FIREWORK_ROCKET)?1:0);}if(item instanceof net.minecraft.world.item.ShieldItem)net.minecraft.client.renderer.item.ItemProperties.register(item,ResourceLocation.withDefaultNamespace("blocking"),(stack,level,entity,seed)->entity!=null&&entity.isUsingItem()&&entity.getUseItem()==stack?1:0);if(item instanceof net.minecraft.world.item.FishingRodItem)net.minecraft.client.renderer.item.ItemProperties.register(item,ResourceLocation.withDefaultNamespace("cast"),(stack,level,entity,seed)->entity instanceof net.minecraft.world.entity.player.Player p&&p.fishing!=null&&(p.getMainHandItem()==stack||(!(p.getMainHandItem().getItem() instanceof net.minecraft.world.item.FishingRodItem)&&p.getOffhandItem()==stack))?1:0);}});}
 private static final class Model extends GeoModel<CursedOne>{
  public ResourceLocation getModelResource(CursedOne mob){return ResourceLocation.fromNamespaceAndPath("zianmobs","geo/"+mob.asset()+".geo.json");}
  public ResourceLocation getTextureResource(CursedOne mob){return ResourceLocation.fromNamespaceAndPath("zianmobs","textures/entity/"+mob.asset()+".png");}
  public ResourceLocation getAnimationResource(CursedOne mob){return ResourceLocation.fromNamespaceAndPath("zianmobs","animations/"+mob.asset()+".animation.json");}
 }
}
